sysauto_script.script:
(function() {
    var gr = new GlideRecord('x_2098628_ds_ent_0_access_request');
    gr.addQuery('active', true);
    gr.addQuery('expiry_date', '<=', gs.daysAgoEnd(0));
    gr.addQuery('overall_status', '!=', 'revoked');
    gr.query();

    gs.info('DEBUG: Total expired records found = ' + gr.getRowCount());

    while (gr.next()) {
        gs.info('DEBUG: Processing record number -> ' + gr.getValue('number') + ' (sys_id: '  + gr.getUniqueValue() + ')');
        try {
            var inputs = {};
            // Passing the GlideRecord object directly to the record input type
            inputs['access_request_record'] = gr; 

            sn_fd.FlowAPI.executeSubflow('x_2098628_ds_ent_0.automated_access_revocation_handler', inputs);

            gs.info('DEBUG: Successfully triggered subflow for record: ' + gr.getValue('number'));
        } catch (ex) {
            gs.error('DEBUG ERROR in revocation subflow: ' + ex.getMessage());
        }
    }
})();
